script:
const $ = (sel) => document.querySelector(sel)
function cpuPercent() {
  const h = dsh.history('host')
  const out = []
  for (let i = 1; i < h.length; i++) {
    const [b0, t0] = h[i - 1].value.cpu, [b1, t1] = h[i].value.cpu
    if (t1 > t0) out.push((b1 - b0) / (t1 - t0))
  }
  return out
}
dsh.onData((data) => {
  const r = data.sources.host
  const err = $('.err')
  if (!r) return
  if (!r.ok) { err.hidden = false; err.textContent = r.error; return }
  err.hidden = true
  const v = r.value
  const cpu = cpuPercent()
  const now = cpu.length ? cpu[cpu.length - 1] : null
  $('#cpu .v').textContent = now == null ? '…' : dsh.fmt.percent(now)
  $('#cpu .v').style.color = now == null ? '' : dsh.tone(now)
  $('#cpu .spark').innerHTML = dsh.chart.sparkline(cpu.map((x) => x * 100), { width: 280, height: 30, min: 0, max: 100 })
  const [mt, ma] = v.mem, mu = (mt - ma) / mt
  $('#mem .v').textContent = dsh.fmt.percent(mu)
  $('#mem .bar').innerHTML = dsh.chart.bar(mu)
  $('#mem .sub').textContent = dsh.fmt.bytes(mt - ma) + ' / ' + dsh.fmt.bytes(mt)
  const [dt, du] = v.disk, df = du / dt
  $('#disk .v').textContent = dsh.fmt.percent(df)
  $('#disk .bar').innerHTML = dsh.chart.bar(df)
  $('#disk .sub').textContent = dsh.fmt.bytes(du) + ' / ' + dsh.fmt.bytes(dt)
  const [l1, l5, l15] = v.load
  $('#load .v').textContent = l1.toFixed(2)
  $('#load .v').style.color = dsh.tone(l1 / v.cores)
  $('#load .sub').textContent = '5 分钟 ' + l5.toFixed(2) + ' · 15 分钟 ' + l15.toFixed(2) + ' · ' + v.cores + ' 核 · 已运行 ' + dsh.fmt.duration(v.uptime)
})
